package app.xiaohe.tests;

import android.app.Instrumentation;
import org.json.*;

/** Two trusted Send touches exercise the existing WebView and production native bridge. */
final class MemoryAnswerUiSmoke {
  static void input(Instrumentation test,MemoryAnswerSupport.Session s,String text)throws Exception{MemoryAnswerSupport.js(test,s.web,"(()=>{const e=document.getElementById('message-input');e.value="+JSONObject.quote(text)+";e.dispatchEvent(new Event('input',{bubbles:true}));changeView('chat');return true;})()");MemoryAnswerSupport.hideKeyboard(test,s.web);MemoryAnswerSupport.wait(test,s.web,"!state.busy&&pendingCalls.size===0&&!document.getElementById('send').disabled","Ordinary Send is ready");}
  static JSONArray run(Instrumentation test)throws Exception{JSONArray report=new JSONArray();try(MemoryAnswerSupport.Session s=new MemoryAnswerSupport.Session(test)){
    MemoryAnswerSupport.Gifts gifts=new MemoryAnswerSupport.Gifts(s.db(),true);MemoryAnswerSupport.js(test,s.web,"loadData("+s.db().bootstrap()+");true");JSONObject before=MemoryAnswerSupport.digest(s.db());
    MemoryAnswerSupport.lastScenario="ui-first-query";s.server.responder=request->MemoryAnswerSupport.query("合成甲婚礼那次，你送了1200元份子钱。",gifts.a);input(test,s,"合成甲婚礼那次，我给了多少份子钱？");MemoryAnswerSupport.check(s.server.count()==0,"Typing a draft does not send a model request");MemoryAnswerSupport.tap(test,s.web,"#send");MemoryAnswerSupport.wait(test,s.web,"!state.busy&&pendingCalls.size===0&&state.messages.some(m=>m.role==='assistant'&&String(m.content).includes('1200'))","Actual first UI answer arrived");MemoryAnswerSupport.check(s.server.count()==1,"One request after one trusted Send");MemoryAnswerSupport.readonly(before,s.db());
    MemoryAnswerSupport.lastScenario="ui-plural-followup";s.server.responder=request->MemoryAnswerSupport.query("你过去给合成甲1200元、合成乙1800元。它们是历史往来的参考，对方这次实际送多少还没有记录。",gifts.a,gifts.b);input(test,s,"现在轮到我，他们该给我回多少");MemoryAnswerSupport.check(s.server.count()==1,"Follow-up stays an editable draft until trusted Send");MemoryAnswerSupport.tap(test,s.web,"#send");MemoryAnswerSupport.wait(test,s.web,"!state.busy&&pendingCalls.size===0&&state.messages.some(m=>m.role==='assistant'&&String(m.content).includes('1200')&&String(m.content).includes('1800'))","Actual plural answer includes both known amounts");s.server.healthy();MemoryAnswerSupport.check(s.server.count()==2,"Two explicit UI queries caused exactly two model requests");MemoryAnswerSupport.readonly(before,s.db());JSONArray rows=MemoryAnswerSupport.candidates(s.server.last());MemoryAnswerSupport.check(MemoryAnswerSupport.has(rows,gifts.a.getString("id"))&&MemoryAnswerSupport.has(rows,gifts.b.getString("id")),"Actual plural WebView send recalled window-excluded and archived evidence");
    String selector=".message.assistant button[data-memory=\""+gifts.b.getString("id")+"\"]";MemoryAnswerSupport.wait(test,s.web,"!!document.querySelector("+JSONObject.quote(selector)+")","Assistant renders a native-validated evidence entry even outside bootstrap");MemoryAnswerSupport.screenshot(test,s.web,"plural-known-amounts-readonly");report.put(new JSONObject().put("scenario","real-ui-plural-followup").put("trustedSends",2).put("modelRequests",s.server.count()).put("sentIds",MemoryAnswerSupport.ids(rows)).put("readOnly",before));
    MemoryAnswerSupport.lastScenario="ui-evidence-outside-bootstrap";MemoryAnswerSupport.hideKeyboard(test,s.web);MemoryAnswerSupport.tap(test,s.web,selector);MemoryAnswerSupport.wait(test,s.web,"document.getElementById('detail-dialog').open&&String(document.getElementById('detail-dialog').innerText).includes('1800')","Actual evidence entry fetches archived original outside initial window");MemoryAnswerSupport.check(s.server.count()==2,"Opening evidence does not call AI");MemoryAnswerSupport.readonly(before,s.db());MemoryAnswerSupport.screenshot(test,s.web,"archived-original-evidence");report.put(new JSONObject().put("scenario","archived-evidence-open").put("noModelRequest",true).put("originalAmount",1800));
  }return report;}
}
